// Excepción a propósito (17-nov): Crating Express (empresa 1) tiene motor propio, Marco, que es un flujo
// exclusivo de CE y lleva su lógica (cotizador, cajones). Todas las demás empresas van al motor genérico
// (Sales AI). G54 no tiene hoy un dato por empresa que diga "esta empresa usa motor propio"; cuando lo
// tenga, este 1 se reemplaza por ese dato. No es un descuido: no sumar otras empresas acá.
const body = $json.body || $json;
const empresaId = Number(body.empresa_id || 0);
const targetUrl = empresaId === 1
  ? 'https://n8n.mdarthurdigital.com/webhook/telegram-marco-g54'
  : 'https://n8n.mdarthurdigital.com/webhook/sales-telegram-g54';
return [{ json: { targetUrl, body } }];

// 16-nov (revisión, punto 10): los envíos "siguen si fallan" para no cortar el guardado del lead,
// así que un envío rechazado (token vencido, ventana de 24 h, cuenta bloqueada…) terminaba como éxito y nadie
// se enteraba. Este paso no corta nada: si el envío falló, arma un aviso por correo; si salió bien, no devuelve nada.
const r = $json || {};
let motivo = '';
if (r.error) motivo = r.error.message || r.error.description || JSON.stringify(r.error);
else if (r.ok === false || r.success === false) motivo = r.message || r.motivo || r.description || 'La API respondió ok: false';
if (!motivo) return [];
const ocultar = s => { const t = String(s || ''); return t.length > 4 ? '…' + t.slice(-4) : t; };

let d = {};
try { d = $('🔀 Decidir Destino').first().json; } catch (e) {}
const agente = 'Router de Telegram';
const empresa = 'empresa ' + ((d.body || {}).empresa_id || '?');
const canal = 'Telegram (reenvío al motor)';
const contacto = String(((d.body || {}).chat_id) || ((d.body || {}).contact_id) || '');

const asunto = `⚠️ G54: la respuesta no le llegó al cliente (${empresa}, ${canal})`;
const html = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#1d2420">
<p>El agente <b>${agente}</b> generó una respuesta pero el envío falló. El cliente no la recibió.</p>
<p>Empresa: ${empresa}<br>Canal: ${canal}<br>Contacto: ${ocultar(contacto)}<br>Ejecución: ${$execution.id}</p>
<p style="background:#fdecea;padding:12px;border-radius:6px">Motivo: ${String(motivo).slice(0, 500).replace(/[<>&]/g, '')}</p>
<p>Revisá el token o la configuración del canal en G54 y respondele a mano desde el panel.</p></div>`;
return [{ json: { asunto, html } }];
